<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { database, makePairs, shuffle, progress } from '../store'
import { memoryCards, memoryStats, pairErrorCount } from '../pairs'
import type { MemoryFilter } from '../pairs'
import StressWord from './StressWord.vue'
import WordContext from './WordContext.vue'
const pairs = computed(() => makePairs(database.value.words))
const filter = ref<MemoryFilter>('all')
const filterItems = [{ title: 'Все пары', value: 'all' }, { title: 'Мои ошибки', value: 'mistakes' }, { title: 'Чаще всего ошибаюсь', value: 'frequent' }]
const stats = computed(() => memoryStats(database.value.words, progress.mistakeCounts, progress.mistakes))
const filteredPairs = computed(() => memoryCards(database.value.words, pairs.value, filter.value, stats.value))
const order = ref<string[]>([])
const index = ref(0), revealed = ref(false)
const saved = ref<string[]>([])
const displayPairs = computed(() => order.value.length ? order.value.map(id => filteredPairs.value.find(p => p.id === id)).filter((p): p is NonNullable<typeof p> => !!p) : filteredPairs.value)
const pair = computed(() => displayPairs.value[index.value % Math.max(displayPairs.value.length, 1)])
function next() { if (!displayPairs.value.length) return; index.value = (index.value + 1) % displayPairs.value.length; revealed.value = false }
function shufflePairs() { const cards = shuffle(filteredPairs.value); if (filter.value === 'frequent') cards.sort((a, b) => pairErrorCount(b, stats.value) - pairErrorCount(a, stats.value)); order.value = cards.map(p => p.id); index.value = 0; revealed.value = false }
function toggleSaved() { if (!pair.value) return; saved.value = saved.value.includes(pair.value.id) ? saved.value.filter(id => id !== pair.value.id) : [...saved.value, pair.value.id] }
watch(filter, () => { index.value = 0; revealed.value = false; order.value = [] })
watch(() => displayPairs.value.length, () => { index.value = 0; revealed.value = false })
</script>
<template>
  <div class="page-heading"><div><router-link to="/" class="back-link"><v-icon icon="mdi-arrow-left" size="16" />К темам</router-link><h1>Вместе запоминается<span class="heading-dot">.</span></h1><p>Два слова, один созвучный акцент. Прочитай их вслух.</p></div><span class="subtle-pill">{{ filter === 'all' ? pairs.length + ' пар из твоей базы' : displayPairs.length + ' карточек' }}</span></div>
  <div class="practice-layout"><section><div class="memory-filter"><v-select v-model="filter" :items="filterItems" label="Что повторим?" variant="outlined" density="comfortable" hide-details /><p class="training-description">{{ filter === 'frequent' ? 'Карточки с твоими ошибками из квизов: сначала те, где суммарно больше ошибок. Число ошибок учитывается с этого обновления; прежние отметки сохранены без точного количества.' : filter === 'mistakes' ? 'Пары и отдельные слова из текущего списка ошибок. Правильный ответ в квизе убирает слово из этого списка.' : 'Все созвучные пары из твоей базы. Выбери фильтр, чтобы повторить слова, в которых ты ошибаешься.' }}</p></div><div class="memory-toolbar"><span>КАРТОЧКА {{ displayPairs.length ? index + 1 : 0 }} / {{ displayPairs.length }}</span><v-btn variant="text" prepend-icon="mdi-shuffle-variant" :disabled="!displayPairs.length" @click="shufflePairs">{{ filter === 'frequent' ? 'Перемешать равные' : 'Перемешать' }}</v-btn></div><v-card v-if="pair" class="memory-card"><div class="memory-spark">✳</div><div class="eyebrow">{{ pair.b ? 'ЗАПОМНИ ПАРУ' : 'ЗАПОМНИ СЛОВО' }}</div><div v-if="filter !== 'all'" class="memory-error-count">{{ pairErrorCount(pair, stats) ? (pair.b ? 'Учтено ошибок в этой паре: ' : 'Учтено ошибок в этом слове: ') + pairErrorCount(pair, stats) : 'Ранее отмеченная ошибка · точное число не сохранено' }}</div><div class="pair-words"><WordContext :entry="pair.a"><StressWord :word="revealed ? pair.a.correct : pair.a.word" /></WordContext><template v-if="pair.b"><span class="pair-dash">—</span><WordContext :entry="pair.b"><StressWord :word="revealed ? pair.b.correct : pair.b.word" /></WordContext></template></div><p v-if="!revealed">{{ pair.b ? 'Попробуй поставить ударения самостоятельно.' : 'Попробуй поставить ударение самостоятельно.' }}</p><p v-else-if="pair.b" class="pair-explanation">Общая ударная часть: <strong>«{{ pair.tail }}»</strong>.<br>Проговори пару вместе, чтобы закрепить созвучие.</p><p v-else class="pair-explanation">Проговори слово вслух с правильным ударением.<br>Для этого слова в базе пока нет созвучной пары.</p><v-btn v-if="!revealed" color="primary" size="large" prepend-icon="mdi-eye-outline" @click="revealed = true">{{ pair.b ? 'Показать ударения' : 'Показать ударение' }}</v-btn><v-btn v-else color="primary" size="large" append-icon="mdi-arrow-right" @click="next">Следующая карточка</v-btn><div class="memory-card-foot"><v-btn variant="text" :prepend-icon="saved.includes(pair.id) ? 'mdi-bookmark-check' : 'mdi-bookmark-outline'" @click="toggleSaved">{{ saved.includes(pair.id) ? 'Отмечено в этой сессии' : 'Отметить карточку' }}</v-btn><v-btn v-if="!revealed" variant="text" @click="next">Пропустить <v-icon icon="mdi-arrow-right" size="17" /></v-btn></div></v-card><v-card v-else class="empty-card"><h2>{{ filter === 'all' ? 'Пары пока не найдены' : 'Нет карточек с ошибками' }}</h2><p>{{ filter === 'all' ? 'В текущей базе нет слов с подходящим созвучием.' : 'Ошибки появляются после неверных ответов в квизах. Если у слова нет созвучного напарника, оно будет показано отдельной карточкой.' }}</p><v-btn v-if="filter !== 'all'" variant="tonal" color="primary" @click="filter = 'all'">Все пары</v-btn><v-btn v-if="filter !== 'all'" to="/quiz" variant="text" color="primary">Перейти к квизам</v-btn></v-card><div class="memory-note"><v-icon icon="mdi-information-outline" size="20" /><p>Пары подобраны по совпадению части слова от ударной гласной до конца. Это приём запоминания, а не правило о корне или окончании. В фильтрах ошибок слова без пары показываются отдельными карточками.</p></div></section><aside class="practice-aside"><span class="aside-flower">✳</span><h3>У слов тоже<br>бывают напарники.</h3><p>Созвучия помогают удерживать ударение в памяти. Сначала вспомни знакомое слово, затем — его пару.</p><div class="aside-rule"></div><h4>Как тренироваться</h4><ol><li>Прочитай оба слова.</li><li>Поставь ударения в уме.</li><li>Открой ответ и повтори вслух.</li></ol><router-link to="/quiz">Проверить себя в квизе <v-icon icon="mdi-arrow-right" size="16" /></router-link></aside></div>
</template>
